import { comparer, runInAction, set } from "mobx";
import * as os from "os";
import * as vscode from "vscode";
import { store } from ".";
import { EXTENSION_NAME } from "../constants";
import {
  discoverToursFromRoot,
  MAIN_TOUR_FILES,
  tourDirectories,
  visibleTours
} from "../core/tourDiscovery";
import { readUriContents, updateMarkerTitles } from "../utils";
import { endCurrentCodeTour } from "./actions";

export { MAIN_TOUR_FILES };

const HAS_TOURS_KEY = `${EXTENSION_NAME}:hasTours`;
const PLATFORM = os.platform();
const TOUR_CONTEXT = {
  isLinux: PLATFORM === "linux",
  isMac: PLATFORM === "darwin",
  isWindows: PLATFORM === "win32",
  isWeb: vscode.env.uiKind === vscode.UIKind.Web
};

const customDirectory = vscode.workspace
  .getConfiguration(EXTENSION_NAME)
  .get<string | null>("customTourDirectory", null);

export async function discoverTours(): Promise<void> {
  const tours = await Promise.all(
    vscode.workspace.workspaceFolders!.map(workspaceFolder =>
      discoverToursFromRoot(workspaceFolder.uri, {
        join: (root, relative) => vscode.Uri.joinPath(root, relative),
        read: readUriContents,
        list: async uri =>
          (await vscode.workspace.fs.readDirectory(uri)).map(([name, type]) => ({
            name,
            isDirectory: type !== vscode.FileType.File &&
              type !== vscode.FileType.SymbolicLink
          })),
        id: uri => decodeURIComponent(uri.toString())
      }, customDirectory)
    )
  );

  runInAction(() => {
    store.tours = visibleTours(tours.flat(), TOUR_CONTEXT);

    if (store.activeTour) {
      const tour = store.tours.find(tour => tour.id === store.activeTour!.tour.id);

      if (tour) {
        if (!comparer.structural(store.activeTour.tour, tour)) {
          // Reload without interrupting the current reading session.
          set(store.activeTour.tour, tour);
        }
      } else {
        endCurrentCodeTour();
      }
    }
  });

  vscode.commands.executeCommand("setContext", HAS_TOURS_KEY, store.hasTours);
  updateMarkerTitles();
}

vscode.workspace.onDidChangeWorkspaceFolders(discoverTours);

const watcher = vscode.workspace.createFileSystemWatcher(
  `**/{${tourDirectories(customDirectory).join(",")}}/**/*.tour`
);

watcher.onDidChange(discoverTours);
watcher.onDidCreate(discoverTours);
watcher.onDidDelete(discoverTours);

        } finally {
          tui.start();
          tui.requestRender(true);
        }
        done(result);
        return { render: () => [], invalidate: () => {} };
      })
    : await runTerminalReader(plan, command, { isInteractive: () => false });
  if (outcome.degraded) {
    ctx.ui.notify(`CodeTour: ${outcome.reason} From the workspace root (${workspace}), run: ${command}`, "warning");
  } else if (outcome.exitCode !== 0) {
    ctx.ui.notify(`CodeTour: the reader ended (${outcome.signal || outcome.exitCode}).`, "warning");
  }
}

export default function codetourPlugin(pi: ExtensionAPI) {
  // The response window of DESIGN §4: `agent_start` opens it and
  // `agent_settled` closes it. Pi exposes no response identity (#323 recon
  // §5.c), so the boundary is this instant, compared with the creation
  // records' own `at`.
  let responseStart: number | undefined;
  // The usage of the last run's assistant messages, and how many starts and
  // ends the response contained. Either can repeat or be missing on recovery.
  let runUsages: unknown[] = [];
  let runCount = 0;
  let runStarts = 0;

  // Observability must not become a chorus: one report per response window,
  // and one opening dialogue per created Tour whatever the host re-emits.
  const reportedResponses = new Set<number>();
  const offeredTours = new Set<string>();

  /**
   * The end-of-response report: the Tours this response created, then its
   * single token reading. Silent when no creation is attributed.
   */
  async function reportResponse(
    ctx: ExtensionContext,
    created: CreationRecord[],
    windowStart: number
  ): Promise<void> {
    for (const line of summaryLines(created)) {
      ctx.ui.notify(line, "info");
    }
    // The reading is exact only when it covers the whole response: a single
    // run, whose messages `agent_end` delivered. A repeated run (retry,
    // compaction retry, queued follow-up) leaves only the last one, and the
    // session entries cannot be bounded to the response at all, so both are
    // labelled approximate.
    const fromRun = runUsages.length > 0;
    const usages = fromRun ? runUsages : sessionUsages(ctx, windowStart);
    const approximate = !fromRun || runCount !== 1 || runStarts !== 1;
    ctx.ui.notify(tokenLine(tokenReading(usages, { approximate })), "info");
  }

  /**
   * The opening dialogue of ticket #242, re-pointed at the creation journal:
   * the real interactive reader in this terminal, or the Tour at its active
   * step in VS Code. Never a textual summary, never an independent window, and
   * never a second question for the same Tour.
   */
  async function offerReader(
    ctx: ExtensionContext,
    record: CreationRecord,
    workspace: string
  ): Promise<void> {
    const key = `${record.tourPath}|${record.at}`;
    if (offeredTours.has(key)) return;
    offeredTours.add(key);
    // Print and JSON modes have no dialogue to offer (ctx.hasUI === false).
    if (ctx.hasUI === false) return;
    const tour = { tourPath: record.tourPath, tourTitle: record.tourTitle, workspace };
    const question = openingQuestion(tour);
    if (!question) return;
    const choice = await ctx.ui.select(question, openingOptions());
    const words = cliWords(await installedLauncher());
    if (choice === TERMINAL_OPTION) {
      // The real reader opens immediately: the installed CLI is spawned with
      // inherited stdio — this very terminal, never an independent window — and
      // the call returns only when the reading ends. A non-interactive session
      // or a failed spawn degrades to the documented hand-over command.
      const outcome = await playInTerminal(tour, { command: words[0], args: words.slice(1) });
      if (outcome.degraded && outcome.command) {
        ctx.ui.notify(
          outcome.reason
            ? `CodeTour: ${outcome.reason} Run ${outcome.command} at the ` +
              "workspace root — the reader plays in this terminal, never an independent window."
            : `Run ${outcome.command} at the workspace root — the reader plays ` +
              "in this terminal, never an independent window.",
          "warning"
        );
      } else if (outcome.played && outcome.exitCode !== 0) {
        ctx.ui.notify(
          `CodeTour: the reader ended (${outcome.signal || outcome.exitCode}); ` +
            "the terminal is back with your session.",
          "warning"
        );
      }
    } else if (choice === VSCODE_OPTION) {
      const command = vscodeCommand(tour);
      if (!command) {
        ctx.ui.notify("CodeTour: the created Tour has no path to open in VS Code.", "warning");
        return;
      }
      try {
        const result = await pi.exec(
          words[0],
          [...words.slice(1), "--internal-open-vscode", record.tourPath, ctx.cwd],
          { cwd: ctx.cwd }
        );
        if (result.code !== 0) {
          ctx.ui.notify(
            `CodeTour: could not open the Tour in VS Code: ${
              result.stderr.trim() || `exit ${result.code}`
            }. Run ${command} at the workspace root.`,
            "warning"
          );
        }
      } catch (error) {
        ctx.ui.notify(
          `CodeTour: could not open the Tour in VS Code: ${
            error instanceof Error ? error.message : String(error)
          }. Run ${command} at the workspace root.`,
          "warning"
        );
      }
    }
  }

  // The window opens at the first run of the response, so a retry or a queued
  // follow-up does not hide the creations of the runs before it.
  pi.on("agent_start", () => {
    if (responseStart === undefined) {
      responseStart = Date.now();
      runCount = 0;
      runStarts = 0;
    }
    runStarts += 1;
    runUsages = [];
  });

  pi.on("agent_end", (event) => {
    runCount += 1;
    runUsages = responseUsages(event);
  });

  // `agent_settled` is Pi's final, notification-only boundary: it cannot ask
  // for a continuation, it fires once per settled response, and it is emitted
  // in print mode too. Nothing below returns a value.
  pi.on("agent_settled", async (event, ctx) => {
    const start = responseStart;
    responseStart = undefined;
    if (event?.aborted === true || start === undefined) return;
    if (reportedResponses.has(start)) return;
    reportedResponses.add(start);
    try {
      const workspace = await realWorkspace(ctx.cwd);
      if (!workspace) return;
      const { records } = await readCreations(workspace);
      const created = selectCreated(records, {
        workspace,
        sessionId: ctx.sessionManager.getSessionId(),
        since: start,
        now: Date.now(),
      }) as CreationRecord[];
      if (created.length === 0) return;
      await reportResponse(ctx, created, start);
      for (const record of created) {
        // One dialogue per Tour: a host that cannot open one still gets the
        // report, and the next Tour keeps its own offer.
        try {
          await offerReader(ctx, record, workspace);
        } catch {
          // An opening never fails the response.
        }
      }
    } catch {
      // The journal is observability only: a reading failure is never a
      // response failure and never a Tour to report.
    }
  });

  pi.registerCommand("codetour", {
    description: "Read an existing CodeTour: /codetour read [tour]; generate one: /codetour generate",
    handler: async (rawArgs, ctx) => {
      let input = rawArgs.trim();
      if (!input) {
        const choice = await ctx.ui.select("CodeTour", ["Generate", "Read"]);
        if (choice === undefined) return;
        input = choice === "Generate" ? "generate" : "read";
      }
      if (/^read(?:\s|$)/.test(input)) {
        const title = input.slice(4).trim().replace(/^(["'])(.*)\1$/, "$2");
        try {
          await readTour(pi, ctx, title);
        } catch (error) {
          ctx.ui.notify(`CodeTour: ${error instanceof Error ? error.message : String(error)}`, "error");
        }
        return;
      }

const CAN_EDIT_TOUR_KEY = `${EXTENSION_NAME}:canEditTour`;
const IN_TOUR_KEY = `${EXTENSION_NAME}:inTour`;
const RECORDING_KEY = `${EXTENSION_NAME}:recording`;
export const EDITING_KEY = `${EXTENSION_NAME}:isEditing`;

const _onDidEndTour = new EventEmitter<CodeTour>();
export const onDidEndTour = _onDidEndTour.event;

const _onDidStartTour = new EventEmitter<[CodeTour, number]>();
export const onDidStartTour = _onDidStartTour.event;

export async function startCodeTourByUri(tourUri: Uri, stepNumber?: number) {
  const bytes = await workspace.fs.readFile(tourUri);
  const contents = new TextDecoder().decode(bytes);
  const tour = loadTour(contents, tourUri.toString());

  startCodeTour(tour, stepNumber);
}

export function startCodeTour(
  tour: CodeTour,
  stepNumber?: number,
  workspaceRoot?: Uri,
  startInEditMode: boolean = false,
  canEditTour: boolean = true,
  tours?: CodeTour[]
) {
  const targetStep = tour.steps.length ? Math.max(0, Math.min(Number.isInteger(stepNumber) ? stepNumber! : 0, tour.steps.length - 1)) : -1;
  const sameStep =
    store.activeTour?.tour.id === tour.id &&
    store.activeTour?.step === targetStep;

  // Starting another tour or another step leaves the current one: the
  // author decides what happens to their unsaved draft first. The start is
  // deferred, never silently dropped, and runs once the draft is resolved.
  if (hasUnsavedStepDraft() && !sameStep) {
    return (async () => {
      if (await resolveStepDraftBeforeExit()) {
        startCodeTourInternal(
          tour,
          stepNumber,
          workspaceRoot,
          startInEditMode,
          canEditTour,
          tours
        );
      }
    })();
  }

  startCodeTourInternal(
    tour,
    stepNumber,
    workspaceRoot,
    startInEditMode,
    canEditTour,
    tours
  );
}

function startCodeTourInternal(
  tour: CodeTour,
  stepNumber?: number,
  workspaceRoot?: Uri,
  startInEditMode: boolean = false,
  canEditTour: boolean = true,
  tours?: CodeTour[]
) {
  startPlayer();

  if (!workspaceRoot) {
    workspaceRoot = getWorkspaceUri(tour);
  }

  const step = tour.steps.length ? Math.max(0, Math.min(Number.isInteger(stepNumber) ? stepNumber! : 0, tour.steps.length - 1)) : -1;
  store.activeTour = {
    tour,
    step,
    workspaceRoot,
    thread: null,
    tours
  };

  commands.executeCommand("setContext", IN_TOUR_KEY, true);
  commands.executeCommand("setContext", CAN_EDIT_TOUR_KEY, canEditTour);
  store.canEditTour = canEditTour;

  if (startInEditMode) {
    store.isRecording = true;
    store.isEditing = true;
    commands.executeCommand("setContext", RECORDING_KEY, true);
    commands.executeCommand("setContext", EDITING_KEY, true);
  } else {
    _onDidStartTour.fire([tour, step]);
  }
}

export async function selectTour(
  tours: CodeTour[],
  workspaceRoot?: Uri,
  step: number = 0
): Promise<boolean> {
  const items: any[] = tours.map(tour => ({
    label: tour.title!,
    tour: tour,
    detail: tour.description
  }));

  if (items.length === 1) {
    startCodeTour(items[0].tour, step, workspaceRoot, false, true, tours);
    return true;
  }

  const response = await window.showQuickPick(items, {
    placeHolder: "Select the tour to start..."
  });

  if (response) {
    startCodeTour(response.tour, 0, workspaceRoot, false, true, tours);
    return true;
  }

  return false;
}

export async function endCurrentCodeTour(fireEvent: boolean = true) {
  if (!store.activeTour || !(await resolveStepDraftBeforeExit())) return;
  if (fireEvent) {
    _onDidEndTour.fire(store.activeTour!.tour);
  }

  if (store.isRecording) {
    store.isRecording = false;
    store.isEditing = false;
    commands.executeCommand("setContext", RECORDING_KEY, false);
    commands.executeCommand("setContext", EDITING_KEY, false);
  } else if (store.isEditing) {
    // Ending the tour also leaves a step editing session: the editing
    // state is cleared while the in-memory draft stays available.
    endEditingSession();
  }

  stopPlayer();

  store.activeTour = null;
  commands.executeCommand("setContext", IN_TOUR_KEY, false);

  window.visibleTextEditors.forEach(editor => {
    if (
      editor.document.uri.scheme === FS_SCHEME ||
      editor.document.uri.scheme === FS_SCHEME_CONTENT
    ) {
      editor.hide();
    }
  });
}

export async function moveCurrentCodeTourBackward() {
  if (!store.activeTour || store.activeTour.step <= 0) return;
  // Leaving the current step goes through the draft guard first: the move
  // only happens once the author's draft is resolved.
  if (!(await resolveStepDraftBeforeExit())) {
    return;
  }

  if (!store.activeTour) return;
  store.activeTour.step = Math.max(0, store.activeTour.step - 1);

  _onDidStartTour.fire([store.activeTour!.tour, store.activeTour!.step]);
}

export async function moveCurrentCodeTourForward() {
  if (!store.activeTour || store.activeTour.step >= store.activeTour.tour.steps.length - 1) return;
  if (!(await resolveStepDraftBeforeExit())) {
    return;
  }

  await progress.update();

  if (!store.activeTour) return;
  store.activeTour.step = Math.min(store.activeTour.tour.steps.length - 1, store.activeTour.step + 1);

  _onDidStartTour.fire([store.activeTour!.tour, store.activeTour!.step]);
}

